PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS repositories(id TEXT PRIMARY KEY,name TEXT,type TEXT,color TEXT,description TEXT);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT,email TEXT UNIQUE,password TEXT,role TEXT,department TEXT,scope TEXT,status TEXT DEFAULT 'active',must_change INTEGER DEFAULT 0,external_hrm_id TEXT,mfa_secret TEXT);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),created_at TEXT,last_active TEXT,csrf TEXT);
CREATE TABLE IF NOT EXISTS folders(id TEXT PRIMARY KEY,name TEXT,repository_id TEXT REFERENCES repositories(id),parent_id TEXT REFERENCES folders(id),description TEXT DEFAULT '',approvers TEXT,metadata_schema TEXT,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,name TEXT,folder_id TEXT REFERENCES folders(id),type TEXT,mime TEXT,size INTEGER,description TEXT,access TEXT DEFAULT 'PRIVATE',downloadable INTEGER DEFAULT 0,publication TEXT DEFAULT 'DRAFT',processing TEXT DEFAULT 'pending_scan',object_key TEXT,preview_key TEXT,fulltext TEXT DEFAULT '',version INTEGER DEFAULT 1,metadata TEXT DEFAULT '{}',effective_from TEXT,effective_until TEXT,replacement_id TEXT,legal_hold INTEGER DEFAULT 0,created_by TEXT,created_at TEXT,updated_at TEXT,deleted_at TEXT);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,document_id TEXT REFERENCES documents(id),number INTEGER,object_key TEXT,preview_key TEXT,fulltext TEXT,mime TEXT,size INTEGER,created_at TEXT,created_by TEXT);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY,subject_type TEXT,subject_id TEXT,target_type TEXT,target_id TEXT,action TEXT,effect TEXT,valid_from TEXT,valid_until TEXT,created_by TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS access_requests(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),document_id TEXT REFERENCES documents(id),reason TEXT,status TEXT DEFAULT 'pending',decision_reason TEXT,created_at TEXT,decided_at TEXT,reviewer_id TEXT);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,document_id TEXT REFERENCES documents(id),requester_id TEXT,status TEXT,reason TEXT,reviewer_id TEXT,created_at TEXT,decided_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT,title TEXT,message TEXT,document_id TEXT,read_at TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor_id TEXT,actor_name TEXT,action TEXT,target_id TEXT,target_name TEXT,repository_id TEXT,outcome TEXT,details TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS favorites(user_id TEXT,document_id TEXT,PRIMARY KEY(user_id,document_id));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,type TEXT,document_id TEXT,status TEXT,error TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS password_resets(token_hash TEXT PRIMARY KEY,user_id TEXT,expires_at TEXT);
CREATE TABLE IF NOT EXISTS email_outbox(id TEXT PRIMARY KEY,recipient TEXT,subject TEXT,body TEXT,status TEXT,attempts INTEGER DEFAULT 0,error TEXT,created_at TEXT);
CREATE INDEX IF NOT EXISTS docs_folder ON documents(folder_id,deleted_at);
CREATE INDEX IF NOT EXISTS folder_parent ON folders(parent_id);
CREATE INDEX IF NOT EXISTS grants_target ON grants(target_id,action);
CREATE INDEX IF NOT EXISTS audit_repo ON audit(repository_id,created_at);
CREATE INDEX IF NOT EXISTS session_user ON sessions(user_id);
CREATE VIRTUAL TABLE IF NOT EXISTS document_search USING fts5(document_id UNINDEXED,content, tokenize='unicode61 remove_diacritics 2');
